INSERT INTO public.descargables (id, titulo, descripcion, categoria, version, fecha_actualizacion, url_archivo, conteo_descargas) VALUES
  ('checklist-medidas', 'Checklist de Toma de Medidas (Casa y Clientas)', 'Lista imprimible con las 12 medidas clave para no olvidar ningún contorno antes de trazar.', 'Medidas', 'v1.2', '2026-11-10', '/api/comunidad/recursos/checklist-medidas', 342),
  ('ficha-tecnica-prenda', 'Ficha Técnica de Taller por Prenda', 'Hoja de control de tela, insumos, puntadas, muestras y observaciones por pedido.', 'Taller', 'v1.1', '2026-11-12', '/api/comunidad/recursos/ficha-tecnica-prenda', 219),
  ('tabla-tallas-base', 'Tabla de Tallas Base XS a 3XL (Latinoamérica)', 'Referencia orientativa en centímetros con holguras recomendadas según tipo de tejido.', 'Patronaje', 'v1.0', '2026-11-05', '/api/comunidad/recursos/tabla-tallas-base', 518),
