INSERT INTO public.perfiles (id, nombre_publico, usuario_unico, rol, ciudad_pais, bio, especialidades, nivel, vende_por_encargo, mostrar_contacto, enlace_instagram, publicaciones_aprobadas_count, es_demo) VALUES
  ('00000000-0000-4000-8000-000000000101', 'Marta Elena Ríos (Demo)', 'marta_costura', 'moderadora', 'Medellín, Colombia', 'Modista de taller familiar desde hace 18 años. Amo explicar vistas limpias y escotes cruzados.', ARRAY['Vestidos a medida', 'Ajuste de busto', 'Sastrería liviana'], 'profesional', true, true, '@marta_costura_demo', 14, true),
  ('00000000-0000-4000-8000-000000000102', 'Lucía Méndez (Demo)', 'lucia_taller', 'usuaria', 'Puebla, México', 'Empecé cosiendo para mí en 2024 y ahora confecciono faldas circulares y conjuntos de lino.', ARRAY['Faldas circulares', 'Lino', 'Principiantes'], 'intermedia', false, false, NULL, 6, true),
  ('00000000-0000-4000-8000-000000000103', 'Camila Rojas (Demo)', 'camila_hilos', 'usuaria', 'Lima, Perú', 'Especialista en pantalones palazzo, tiros altos y arreglos de calce.', ARRAY['Pantalones', 'Ajuste de tiro', 'Viscosa'], 'profesional', true, true, '@camila_hilos_demo', 9, true),
  ('00000000-0000-4000-8000-000000000104', 'Valeria Soto (Demo)', 'valeria_puntadas', 'usuaria', 'Santiago, Chile', 'Aprendiendo costura paso a paso con telas de punto, pijamas y ropa infantil.', ARRAY['Infantil', 'Tela de punto', 'Pijamas'], 'aprendiz', false, false, NULL, 3, true),
  ('00000000-0000-4000-8000-000000000105', 'Sofía Herrera (Demo)', 'sofia_patronaje', 'admin', 'San José, Costa Rica', 'Co-creadora de guías técnicas del taller. Reviso medidas, márgenes e impresión 1:1.', ARRAY['Patronaje', 'Sastrería', 'Educación'], 'profesional', false, false, NULL, 12, true),
  ('00000000-0000-4000-8000-000000000106', 'Andrea Morales (Demo)', 'andrea_aguja', 'usuaria', 'Córdoba, Argentina', 'Costura lenta y accesorios útiles: sombreros, delantales y conjuntos de verano.', ARRAY['Accesorios', 'Conjuntos 2 piezas', 'Algodón'], 'intermedia', true, false, NULL, 5, true)
