INSERT INTO public.publicaciones (id, slug, autora_id, titulo, descripcion, aprendizaje_nota, prenda, tela, dificultad, tiempo_horas, costo_aprox, config_molde, captura_3d_url, reto_id, estado, conteo_reacciones, conteo_comentarios, conteo_guardados, conteo_remixes, es_demo, creado_en) VALUES
  ('20000000-0000-4000-8000-000000000001', 'vestido-cruzado-terracota-marta', '00000000-0000-4000-8000-000000000101', 'Vestido cruzado kimono en crepé terracota (Ejemplo)', 'Cosí este vestido cruzado midi para una tarde en el jardín. Usé entretela tricot muy liviana en la vista de 4 cm.', 'Hacer un pespunte de asiento en el escote en V evita por completo que la vista se dé la vuelta.', 'Vestido', 'Crepé / Viscosa', 3, 5.5, '$28 USD', '{"version_config":1,"category":"dress","dressSubStyle":"dress","skirtSubStyle":"a_line","necklineStyle":"v_neck","sleeveStyle":"kimono","torsoFit":"loose","seamAllowance":1,"fabricType":"woven","extras":{"wrapFront":true,"flaredSleeve":false,"waistTie":true,"hemRuffle":false,"sidePockets":false,"flapPockets":false},"quickLength":"midi","styleVariant":"default","apariencia3D":{"tela":"crepe","color":"#C85A32","estampado":"liso"}}', '/promo/01-foto-ia.png', NULL, 'publicada', 24, 3, 19, 12, true, now() - interval '6 days'),
  ('20000000-0000-4000-8000-000000000002', 'falda-circular-lunares-lucia', '00000000-0000-4000-8000-000000000102', 'Falda circular de lunares para el reto del mes (Ejemplo)', 'Mi participación en el reto de falda circular en chalis azul marino con lunares marfil.', 'Dejar colgar la falda 24 h antes de cortar el ruedo hizo que quedara parejita por toda la vuelta.', 'Falda', 'Crepé / Viscosa', 2, 3.0, '$16 USD', '{"version_config":1,"category":"skirt","skirtSubStyle":"semicircular","necklineStyle":"round","sleeveStyle":"sleeveless","torsoFit":"fitted","seamAllowance":1,"fabricType":"woven","extras":{"wrapFront":false,"flaredSleeve":false,"waistTie":false,"hemRuffle":false,"sidePockets":false,"flapPockets":false},"quickLength":"knee","styleVariant":"default","apariencia3D":{"tela":"crepe","color":"#1F2A44","estampado":"lunares"}}', '/promo/05-falda-plan-corte.png', '10000000-0000-4000-8000-000000000001', 'publicada', 31, 4, 27, 15, true, now() - interval '5 days'),
  ('20000000-0000-4000-8000-000000000003', 'pantalon-palazzo-lino-camila', '00000000-0000-4000-8000-000000000103', 'Pantalón palazzo con bolsillos en lino marfil (Ejemplo)', 'Primer pantalón de pinzas y bota ancha usando mis medidas exactas de tiro y muslo.', 'Pre-lavar el lino en agua tibia antes de cortar evitó encogimientos en la bota después del primer lavado.', 'Pantalón', 'Lino / Gabardina', 3, 4.5, '$24 USD', '{"version_config":1,"category":"pants","pantsSubStyle":"wide","necklineStyle":"round","sleeveStyle":"sleeveless","torsoFit":"fitted","seamAllowance":1,"fabricType":"woven","extras":{"wrapFront":false,"flaredSleeve":false,"waistTie":false,"hemRuffle":false,"sidePockets":true,"flapPockets":false},"quickLength":"maxi","styleVariant":"default","apariencia3D":{"tela":"lino","color":"#F3EBDD","estampado":"liso"}}', '/promo/03-molde-pdf.png', NULL, 'publicada', 18, 2, 22, 9, true, now() - interval '5 days'),
  ('20000000-0000-4000-8000-000000000004', 'conjunto-sastre-blazer-marta', '00000000-0000-4000-8000-000000000101', 'Conjunto sastre blazer rayas y pantalón recto (Ejemplo)', 'Conjunto de dos piezas bicolor pensado para oficina: chaqueta con solapa sastre y bolsillos con tapa.', 'Usar plancha de vapor con trapo húmedo en el quiebre de la solapa le da un terminado de sastrería profesional.', 'Chaqueta / Conjunto', 'Lino / Gabardina', 5, 9.0, '$45 USD', '{"version_config":1,"category":"two_piece","twoPieceTopStyle":"jacket_blazer","twoPieceBottomStyle":"pants","pantsSubStyle":"straight","necklineStyle":"tailored_lapel","sleeveStyle":"long","torsoFit":"fitted","seamAllowance":1.5,"fabricType":"woven","extras":{"wrapFront":false,"flaredSleeve":false,"waistTie":false,"hemRuffle":false,"sidePockets":true,"flapPockets":true},"quickLength":"maxi","styleVariant":"default","apariencia3D":{"tela":"lino","color":"#1F2A44","estampado":"rayas","colorSecundario":"#F3EBDD"}}', '/promo/02-medidas-guardadas.png', NULL, 'publicada', 29, 5, 34, 14, true, now() - interval '4 days'),
  ('20000000-0000-4000-8000-000000000005', 'vestido-imperio-vichy-andrea', '00000000-0000-4000-8000-000000000106', 'Vestido corte imperio en cuadros Vichy verde (Ejemplo)', 'Escote cuadrado con manga corta farol y falda semicircular muy fresca para días soleados.', 'Embastar a mano la línea bajo busto antes de pasar la recta hace que el recogido no se mueva nada.', 'Vestido', 'Lino / Gabardina', 3, 5.0, '$22 USD', '{"version_config":1,"category":"dress","dressSubStyle":"dress","skirtSubStyle":"semicircular","necklineStyle":"square","sleeveStyle":"short","torsoFit":"fitted","seamAllowance":1,"fabricType":"woven","extras":{"wrapFront":false,"flaredSleeve":true,"waistTie":false,"hemRuffle":false,"sidePockets":false,"flapPockets":false},"quickLength":"midi","styleVariant":"empire_cut","apariencia3D":{"tela":"lino","color":"#0F7B5F","estampado":"vichy"}}', '/promo/06-revista-guias.png', NULL, 'publicada', 21, 2, 16, 7, true, now() - interval '4 days'),
  ('20000000-0000-4000-8000-000000000006', 'blusa-oficina-seda-sofia', '00000000-0000-4000-8000-000000000105', 'Blusa básica de oficina con pinza de busto (Ejemplo)', 'Blusa de escote redondo en satén vino con costuras francesas por el revés.', 'Usar aguja microtex calibre 70 evita por completo que el satén se frunza o se hale el hilo.', 'Blusa', 'Seda / Satén', 2, 2.5, '$15 USD', '{"version_config":1,"category":"top","topSubStyle":"blouse","necklineStyle":"round","sleeveStyle":"short","torsoFit":"fitted","seamAllowance":1,"fabricType":"woven","extras":{"wrapFront":false,"flaredSleeve":false,"waistTie":false,"hemRuffle":false,"sidePockets":false,"flapPockets":false},"quickLength":"photo","styleVariant":"office_dart","apariencia3D":{"tela":"seda","color":"#6E1F34","estampado":"liso"}}', '/promo/04-cotizador-taller.png', NULL, 'publicada', 15, 1, 14, 11, true, now() - interval '3 days'),
  ('20000000-0000-4000-8000-000000000007', 'conjunto-veraniego-bicolor-andrea', '00000000-0000-4000-8000-000000000106', 'Conjunto crop top marfil y falda larga terracota (Ejemplo)', 'Dos piezas súper cómodas para playa, con pretina ancha y costuras remalladas.', 'Probé primero el crop top en retazo de manta para confirmar la caída del escote cuadrado sin que se abra.', 'Conjunto 2 Piezas', 'Lino / Gabardina', 2, 4.0, '$20 USD', '{"version_config":1,"category":"two_piece","twoPieceTopStyle":"crop_top","twoPieceBottomStyle":"long_skirt","necklineStyle":"square","sleeveStyle":"sleeveless","torsoFit":"fitted","seamAllowance":1,"fabricType":"woven","extras":{"wrapFront":false,"flaredSleeve":false,"waistTie":false,"hemRuffle":false,"sidePockets":false,"flapPockets":false},"quickLength":"maxi","styleVariant":"default","apariencia3D":{"tela":"lino","color":"#F3EBDD","estampado":"liso","colorSecundario":"#C85A32"}}', '/promo/01-foto-ia.png', NULL, 'publicada', 26, 3, 21, 10, true, now() - interval '3 days'),
  ('20000000-0000-4000-8000-000000000008', 'body-bebe-algodon-valeria', '00000000-0000-4000-8000-000000000104', 'Pelele de bebé con broches inferiores en algodón (Ejemplo)', 'Mi primer proyecto infantil para regalo de nacimiento. Quedó suavito y práctico para cambiar pañal.', 'Reforzar la zona de los 3 broches con un cuadrito de entretela de punto da firmeza sin raspar.', 'Infantil y Bebé', 'Licra / Punto', 2, 2.5, '$11 USD', '{"version_config":1,"category":"kids","kidsSubStyle":"baby_bodysuit","necklineStyle":"round","sleeveStyle":"short","torsoFit":"fitted","seamAllowance":1,"fabricType":"stretch","extras":{"wrapFront":false,"flaredSleeve":false,"waistTie":false,"hemRuffle":false,"sidePockets":false,"flapPockets":false},"quickLength":"photo","styleVariant":"default","apariencia3D":{"tela":"licra","color":"#E8C4C0","estampado":"liso"}}', '/promo/02-medidas-guardadas.png', NULL, 'publicada', 19, 2, 13, 6, true, now() - interval '2 days'),
  ('20000000-0000-4000-8000-000000000009', 'vestido-boho-boleros-lucia', '00000000-0000-4000-8000-000000000102', 'Vestido boho con bolero inferior y manga acampanada (Ejemplo)', 'Hecho en viscosa estampada de lunares pequeños; el bolero en el ruedo le da un movimiento precioso.', 'Usar pie de doble arrastre o tensión floja para el fruncido uniforme del bolero me ahorró la mitad del tiempo.', 'Vestido', 'Crepé / Viscosa', 3, 5.0, '$25 USD', '{"version_config":1,"category":"dress","dressSubStyle":"dress","skirtSubStyle":"a_line","necklineStyle":"v_neck","sleeveStyle":"short","torsoFit":"fitted","seamAllowance":1,"fabricType":"woven","extras":{"wrapFront":false,"flaredSleeve":true,"waistTie":false,"hemRuffle":true,"sidePockets":false,"flapPockets":false},"quickLength":"midi","styleVariant":"default","apariencia3D":{"tela":"crepe","color":"#C85A32","estampado":"lunares"}}', '/promo/05-falda-plan-corte.png', NULL, 'publicada', 22, 3, 25, 8, true, now() - interval '2 days'),
  ('20000000-0000-4000-8000-000000000010', 'delantal-taller-bolsillo-sofia', '00000000-0000-4000-8000-000000000105', 'Delantal de taller con bolsillo dividido para tijeras (Ejemplo)', 'Delantal en gabardina verde esmeralda con pespunte reforzado para guardar metro, tiza y descosedor.', 'Hacer atraque en triángulo en las esquinas superiores del bolsillo evita que se descosa por el peso.', 'Accesorios Textiles', 'Lino / Gabardina', 1, 1.8, '$10 USD', '{"version_config":1,"category":"accessories","accessorySubStyle":"apron","necklineStyle":"round","sleeveStyle":"sleeveless","torsoFit":"fitted","seamAllowance":1,"fabricType":"woven","extras":{"wrapFront":false,"flaredSleeve":false,"waistTie":false,"hemRuffle":false,"sidePockets":false,"flapPockets":false},"quickLength":"photo","styleVariant":"default","apariencia3D":{"tela":"lino","color":"#0F7B5F","estampado":"liso"}}', '/promo/04-cotizador-taller.png', NULL, 'publicada', 17, 1, 20, 13, true, now() - interval '1 day'),
  ('20000000-0000-4000-8000-000000000011', 'overol-jardinera-denim-camila', '00000000-0000-4000-8000-000000000103', 'Jardinera overol con tirantes y botones de latón (Ejemplo)', 'Pechera estructurada, tirantes regulables y bolsillos con tapa muy prácticos para trabajo diario.', 'Hacer doble pespunte color mostaza en la pechera y las costuras del tiro imita el terminado denim clásico.', 'Enterizos y Overoles', 'Lino / Gabardina', 4, 6.5, '$32 USD', '{"version_config":1,"category":"jumpsuit","jumpsuitSubStyle":"overall","necklineStyle":"square","sleeveStyle":"sleeveless","torsoFit":"fitted","seamAllowance":1.5,"fabricType":"woven","extras":{"wrapFront":false,"flaredSleeve":false,"waistTie":false,"hemRuffle":false,"sidePockets":true,"flapPockets":true},"quickLength":"maxi","styleVariant":"default","apariencia3D":{"tela":"lino","color":"#1F2A44","estampado":"liso"}}', '/promo/03-molde-pdf.png', NULL, 'publicada', 28, 4, 29, 7, true, now() - interval '18 hours'),
  ('20000000-0000-4000-8000-000000000012', 'neceser-fuelle-cierre-valeria', '00000000-0000-4000-8000-000000000104', 'Neceser con fuelle en caja para guardar pies prensatelas (Ejemplo)', 'Proyecto rápido con retazos de lino y forro impermeable para organizar todos los accesorios de la máquina.', 'Cortar las esquinas en cuadrado de 4 cm con exactitud deja las esquinas del fuelle simétricas.', 'Accesorios Textiles', 'Lino / Gabardina', 1, 1.5, '$8 USD', '{"version_config":1,"category":"accessories","accessorySubStyle":"zipper_pouch","necklineStyle":"round","sleeveStyle":"sleeveless","torsoFit":"fitted","seamAllowance":1,"fabricType":"woven","extras":{"wrapFront":false,"flaredSleeve":false,"waistTie":false,"hemRuffle":false,"sidePockets":false,"flapPockets":false},"quickLength":"photo","styleVariant":"default","apariencia3D":{"tela":"lino","color":"#E8C4C0","estampado":"vichy"}}', '/promo/06-revista-guias.png', NULL, 'publicada', 14, 2, 18, 9, true, now() - interval '6 hours')
