  ('21000000-0000-4000-8000-000000000006', '20000000-0000-4000-8000-000000000006', '/promo/04-cotizador-taller.png', 'Blusa de oficina confeccionada en satén color vino con escote redondo y pinza de busto', 0, 1200, 1500, true),
  ('21000000-0000-4000-8000-000000000007', '20000000-0000-4000-8000-000000000007', '/promo/01-foto-ia.png', 'Conjunto veraniego de crop top en lino marfil sin mangas y falda larga terracota', 0, 1200, 1500, true),
  ('21000000-0000-4000-8000-000000000008', '20000000-0000-4000-8000-000000000008', '/promo/02-medidas-guardadas.png', 'Pelele de bebé en tejido de punto rosa palo con tres broches en el tiro inferior', 0, 1200, 1500, true),
  ('21000000-0000-4000-8000-000000000009', '20000000-0000-4000-8000-000000000009', '/promo/05-falda-plan-corte.png', 'Vestido boho en viscosa terracota de lunares con bolero inferior y mangas acampanadas', 0, 1200, 1500, true),
  ('21000000-0000-4000-8000-000000000010', '20000000-0000-4000-8000-000000000010', '/promo/04-cotizador-taller.png', 'Delantal de taller en gabardina verde esmeralda con cinta de cuello y bolsillo dividido', 0, 1200, 1500, true),
  ('21000000-0000-4000-8000-000000000011', '20000000-0000-4000-8000-000000000011', '/promo/03-molde-pdf.png', 'Overol jardinera en gabardina azul marino con pechera delantera, tirantes y botones de latón', 0, 1200, 1500, true),
