INSERT INTO public.preguntas (id, slug, autora_id, titulo, detalle, categoria, molde_referencia, resuelta, destacada_semana, articulo_blog_slug, conteo_respuestas, es_demo, creado_en) VALUES
  ('30000000-0000-4000-8000-000000000001', 'evitar-escote-cruzado-se-abra-sentarse', '00000000-0000-4000-8000-000000000102', '¿Cómo evitar que el escote cruzado (wrap) se abra al sentarse en crepé? (Ejemplo)', 'Estoy cosiendo mi primer vestido cruzado en viscosa ligera y en la prueba sentí que el escote cede un poco en el pecho. ¿Convendrá pasar un embebido o entretelar toda la vista?', 'costura_acabados', 'Vestido Cruzado Fluido / Kimono', true, true, 'guia-acabados-limpios-vistas-sesgos-dobladillos', 2, true, now() - interval '6 days'),
  ('30000000-0000-4000-8000-000000000002', 'tiro-trasero-tira-pantalon-palazzo', '00000000-0000-4000-8000-000000000104', 'Siento que el tiro trasero me baja un poco al sentarme en el palazzo (Ejemplo)', 'Medí el tiro sentada sobre una silla recta tal como indica el generador, pero en tela gabardina rígida siento tensión atrás al agacharme. ¿Cuántos centímetros agrego en altura de tiro o prolongación trasera?', 'ajustes_molde', 'Pantalón Palazzo / Pierna Ancha', true, false, NULL, 1, true, now() - interval '5 days'),
  ('30000000-0000-4000-8000-000000000003', 'imprimir-hoja-carta-o-a4-sin-que-encojan-marcas', '00000000-0000-4000-8000-000000000104', 'Mi impresora imprime el cuadro de calibración de 5 cm en 4.7 cm, ¿qué opción elijo? (Ejemplo)', 'Descargué el PDF en Hoja Carta y al medir con la regla de taller el cuadro salió un poquito más pequeño. ¿Debo activar Tamaño Real o Sin márgenes?', 'imprimir_armar', 'Blusa Básica de Oficina', true, false, 'como-imprimir-moldes-pdf-en-casa-sin-descuadrar', 1, true, now() - interval '4 days'),
  ('30000000-0000-4000-8000-000000000004', 'cuanta-tela-pedir-falda-circular-larga-150', '00000000-0000-4000-8000-000000000106', '¿Me alcanza 2.5 m de tela de 150 cm de ancho para falda semicircular midi? (Ejemplo)', 'La clienta quiere una falda con bastante vuelo por debajo de la rodilla pero la tela estampada tiene dirección en el dibujo. ¿Cómo optimizo el plan de corte?', 'telas', 'Falda Circular / Plato', true, false, NULL, 1, true, now() - interval '3 days'),
  ('30000000-0000-4000-8000-000000000005', 'tomarme-largo-talle-yo-sola-espejo', '00000000-0000-4000-8000-000000000102', 'Truco para tomarme sola el largo de talle trasero y el ancho de espalda sin variar 2 cm (Ejemplo)', 'Cuando giro el brazo para tocar el hombro siento que altero la postura. ¿Algún método práctico usando una cinta en la cintura?', 'medidas', 'Blusa Básica de Oficina', false, false, NULL, 1, true, now() - interval '2 days'),
  ('30000000-0000-4000-8000-000000000006', 'arrugas-axila-manga-kimono-entallada', '00000000-0000-4000-8000-000000000106', '¿Qué holgura recomiendan en manga kimono para que no tire al levantar los brazos? (Ejemplo)', 'Quiero hacer una blusa kimono pero con cintura algo definida. ¿Paso el selector a Holgado / Blusado o dejo Entallado con 1.5 cm de margen?', 'ajustes_molde', 'Vestido Cruzado Fluido / Kimono', false, false, NULL, 0, true, now() - interval '1 day'),
  ('30000000-0000-4000-8000-000000000007', 'dobladillo-ondulado-seda-satén-sin-fruncir', '00000000-0000-4000-8000-000000000104', '¿Cómo hacer el dobladillo pañuelo en una falda circular de satén sin que haga ondas raras? (Ejemplo)', 'Intenté doblar 1 cm directo con la plancha y quedó revirado por ser corte al bies. ¿Vale la pena pasar un pespunte guía a 0.5 cm antes?', 'costura_acabados', 'Vestido Imperio', true, false, NULL, 1, true, now() - interval '12 hours'),
  ('30000000-0000-4000-8000-000000000008', 'cuanto-cobrar-vestido-cruzado-con-forro', '00000000-0000-4000-8000-000000000103', '¿Cómo presupuestan horas extra cuando una clienta pide forrar un vestido completo? (Ejemplo)', 'Usé el cotizador de Mi Taller para calcular la tela, pero me cuesta decidir cuánto sumar por forrería a mano en sisas y cierres invisibles.', 'negocio_precios', 'Vestido Cruzado Fluido / Kimono', false, false, NULL, 1, true, now() - interval '4 hours')
