-- ============================================================================
-- MoldeFácil Comunidad: Datos de Demostración Claramente Marcados (es_demo = true)
-- Incluye: 5 insignias, etiquetas de selectores, 1 reto mensual, 4 descargables,
-- 6 modistas de ejemplo, 12 publicaciones demo y 8 preguntas demo.
-- ============================================================================

ON CONFLICT (id) DO UPDATE SET
  nombre = EXCLUDED.nombre,
  descripcion = EXCLUDED.descripcion,
  icono = EXCLUDED.icono;

ON CONFLICT (id) DO UPDATE SET
  nombre = EXCLUDED.nombre,
  grupo_selector = EXCLUDED.grupo_selector,
  valor_selector = EXCLUDED.valor_selector;

ON CONFLICT (id) DO UPDATE SET
  titulo = EXCLUDED.titulo,
  version = EXCLUDED.version,
  fecha_actualizacion = EXCLUDED.fecha_actualizacion;

    '10000000-0000-4000-8000-000000000001',
    'falda-circular-tela-estampada',
    'Reto del mes: Falda circular en tela estampada',
    'Cose tu falda circular o semicircular con el estampado que más te ilusione, cuenta cuánto reposó al bies antes del dobladillo e inspira al taller.',
    '1) Usa el molde de falda circular o semicircular de MoldeFácil. 2) Deja colgar la falda 24 horas antes de igualar el ruedo. 3) Sube al menos 1 foto con texto alternativo descriptivo y el permiso de imagen confirmado.',
    '#RetoFaldaCircular',
    'formula-exacta-faldas-circulares-plato-medio-doble',
    '2026-11-01',
    '2026-11-30',
    true
  )
ON CONFLICT (id) DO NOTHING;

