SELECT * FROM (VALUES
  ('40000000-0000-4000-8000-000000000001'::uuid, '30000000-0000-4000-8000-000000000001'::uuid, '00000000-0000-4000-8000-000000000101'::uuid, 'Coloca una cinta estabilizadora al hilo (stay tape o tira de entretela de 1 cm cortada al hilo) justo sobre el borde del escote antes de coser la vista. Además, un mini broche oculto a la altura del busto da tranquilidad total al agacharse.', true, 18),
  ('40000000-0000-4000-8000-000000000002'::uuid, '30000000-0000-4000-8000-000000000002'::uuid, '00000000-0000-4000-8000-000000000103'::uuid, 'En telas rígidas suma +1.5 cm a la altura de tiro en el paso de medidas o sube la costura centro espalda en la pretina 1.5 cm afinando hacia los costados.', true, 11),
  ('40000000-0000-4000-8000-000000000003'::uuid, '30000000-0000-4000-8000-000000000003'::uuid, '00000000-0000-4000-8000-000000000105'::uuid, 'En el cuadro de impresión del navegador desactiva "Ajustar a la página" y elige "Escala 100 %" o "Tamaño real". Si vuelve a dar 4.7 cm, ajusta escala manual a 106 % solo en ese documento.', true, 23),
  ('40000000-0000-4000-8000-000000000004'::uuid, '30000000-0000-4000-8000-000000000004'::uuid, '00000000-0000-4000-8000-000000000101'::uuid, 'Cuando el estampado tiene sentido único conviene dividir la falda semicircular en 2 paneles con costuras al costado (hilo vertical) para evitar que los dibujos queden de cabeza atrás.', true, 9),
  ('40000000-0000-4000-8000-000000000005'::uuid, '30000000-0000-4000-8000-000000000007'::uuid, '00000000-0000-4000-8000-000000000101'::uuid, 'Sí, pasa un pespunte recto a 0.5 cm del borde crudo, dobla sobre esa línea y cose pegadito, recorta el sobrante a 2 mm y vuelve a doblar otro 3 mm. Queda finísimo tipo pañuelo.', true, 14)
) AS r(id, pregunta_id, autora_id, contenido, es_aceptada, conteo_me_sirvio)
ON CONFLICT DO NOTHING;
